export const WORKER_SCRIPT = "\"\"\"NEXUS remote worker (standalone; Python 3.10+ standard library, optional torch / psutil).\n\nThis one file runs a NEXUS ProductionJobManifest on any worker: a Kaggle kernel (pushed by the dispatcher with the job\nbundle embedded below), the local CPU worker, the owner's own GPU PC or a Colab notebook (pull protocol). It must stay\nimportable without the `nexus` package: Kaggle receives only this file.\n\nJob bundle (JSON):\n    {\"job_id\", \"task\", \"params\", \"attempt\", \"provider\", \"connection_id\", \"max_runtime_s\", \"worker_version\",\n     \"inputs\": [{\"name\", \"sha256\"?, \"size\"?, \"b64\"? | \"url\"?}],   # small inputs inline (base64), larger ones by URL\n     \"checkpoint\": JobCheckpoint/v1 dict or null}                     # resume point from an earlier lost/failed run\n\nOutput directory layout (what the dispatcher downloads and verifies):\n    result.json                 WorkerExecutionResult/v1 fields; artifacts carry size + SHA-256\n    checkpoints/ckpt_0001.json  JobCheckpoint/v1, one per completed step (seq continues across attempts)\n    artifacts/<name>            every produced file\n\nAdding a task (Accounts 2/3): write `@task(\"my_task\")\\ndef my_task(ctx): ...` in a file under worker_kit/tasks/\n(it is appended to this file when the dispatcher builds the kernel script) and register its routing needs in\nnexus/cloud/compute/tasks.py (TaskSpec). A task uses only `ctx` (see Context) and returns a dict of extra metrics.\n\"\"\"\nfrom __future__ import annotations\n\nimport base64\nimport hashlib\nimport json\nimport os\nimport platform\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nimport threading\nimport time\nimport traceback\nimport urllib.request\nimport uuid\nfrom pathlib import Path\n\nWORKER_VERSION = \"1.0.0\"\n_EMBEDDED_BUNDLE_B64 = \"\"  # replaced by the dispatcher in the pushed Kaggle script; never contains secrets\n\nTASKS: dict = {}\n\n\ndef task(name: str):\n    def deco(fn):\n        TASKS[name] = fn\n        return fn\n    return deco\n\n\nclass SimulatedWorkerLoss(RuntimeError):\n    \"\"\"Raised by a task when params ask it to stop mid-way (resume demonstrations and tests).\"\"\"\n\n\n# ---------------------------------------------------------------- helpers\ndef sha256_file(p) -> str:\n    h = hashlib.sha256()\n    with open(p, \"rb\") as f:\n        for b in iter(lambda: f.read(1 << 20), b\"\"):\n            h.update(b)\n    return h.hexdigest()\n\n\ndef _run(cmd, timeout=None) -> subprocess.CompletedProcess:\n    return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)\n\n\ndef _mime(name: str) -> str:\n    ext = name.rsplit(\".\", 1)[-1].lower()\n    return {\"mp4\": \"video/mp4\", \"mov\": \"video/quicktime\", \"webm\": \"video/webm\", \"json\": \"application/json\", \"txt\": \"text/plain\",\n            \"png\": \"image/png\", \"jpg\": \"image/jpeg\", \"wav\": \"audio/wav\", \"mp3\": \"audio/mpeg\", \"log\": \"text/plain\"}.get(ext, \"application/octet-stream\")\n\n\ndef gpu_info() -> list:\n    if not shutil.which(\"nvidia-smi\"):\n        return []\n    r = _run([\"nvidia-smi\", \"--query-gpu=name,memory.total,driver_version\", \"--format=csv,noheader,nounits\"], timeout=20)\n    out = []\n    for line in r.stdout.strip().splitlines() if r.returncode == 0 else []:\n        parts = [x.strip() for x in line.split(\",\")]\n        if len(parts) >= 3:\n            out.append({\"name\": parts[0], \"vram_gb\": round(float(parts[1]) / 1024, 2), \"driver\": parts[2]})\n    return out\n\n\ndef _ram() -> dict:\n    try:\n        import psutil\n        vm = psutil.virtual_memory()\n        return {\"ram_total_gb\": round(vm.total / 2 ** 30, 2), \"ram_available_gb\": round(vm.available / 2 ** 30, 2)}\n    except Exception:  # noqa: BLE001\n        info = {}\n        try:\n            for line in Path(\"/proc/meminfo\").read_text().splitlines():\n                k, v = line.split(\":\", 1)\n                info[k] = int(v.split()[0]) * 1024\n            return {\"ram_total_gb\": round(info[\"MemTotal\"] / 2 ** 30, 2), \"ram_available_gb\": round(info.get(\"MemAvailable\", 0) / 2 ** 30, 2)}\n        except Exception:  # noqa: BLE001\n            return {}\n\n\ndef _cpu_times():\n    try:\n        vals = [int(x) for x in Path(\"/proc/stat\").read_text().splitlines()[0].split()[1:]]\n        return sum(vals), vals[3] + (vals[4] if len(vals) > 4 else 0)\n    except Exception:  # noqa: BLE001\n        return None\n\n\nclass Sampler(threading.Thread):\n    \"\"\"Samples GPU utilisation / memory (nvidia-smi) and whole-machine CPU % while the task runs.\"\"\"\n\n    def __init__(self, every: float = 0.5):\n        super().__init__(daemon=True)\n        self.every, self.halt = every, threading.Event()\n        self.gpu: list = []\n        self.cpu: list = []\n        self.has_smi = bool(shutil.which(\"nvidia-smi\"))\n\n    def run(self):\n        last = _cpu_times()\n        while not self.halt.wait(self.every):\n            if self.has_smi:\n                try:\n                    r = _run([\"nvidia-smi\", \"--query-gpu=utilization.gpu,memory.used\", \"--format=csv,noheader,nounits\"], timeout=5)\n                    row = [[float(x) for x in line.split(\",\")] for line in r.stdout.strip().splitlines() if line.strip()]\n                    if row:\n                        self.gpu.append({\"t\": round(time.time(), 2), \"util\": [x[0] for x in row], \"mem_mb\": [x[1] for x in row]})\n                except Exception:  # noqa: BLE001\n                    pass\n            now = _cpu_times()\n            if now and last and now[0] > last[0]:\n                self.cpu.append(round(100.0 * (1 - (now[1] - last[1]) / (now[0] - last[0])), 1))\n            last = now\n\n    def summary(self) -> dict:\n        utils = [u for s in self.gpu for u in s[\"util\"]]\n        mems = [m for s in self.gpu for m in s[\"mem_mb\"]]\n        return {\"gpu_util_samples\": self.gpu[-120:], \"gpu_util_mean\": round(sum(utils) / len(utils), 1) if utils else None,\n                \"gpu_util_max\": max(utils) if utils else None, \"gpu_mem_used_max_mb\": max(mems) if mems else None,\n                \"cpu_percent_mean\": round(sum(self.cpu) / len(self.cpu), 1) if self.cpu else None,\n                \"cpu_percent_max\": max(self.cpu) if self.cpu else None, \"samples\": len(self.cpu)}\n\n\ndef nvenc_available() -> bool:\n    if not (shutil.which(\"ffmpeg\") and gpu_info()):\n        return False\n    r = _run([\"ffmpeg\", \"-hide_banner\", \"-loglevel\", \"error\", \"-f\", \"lavfi\", \"-i\", \"testsrc=size=256x256:rate=10\", \"-t\", \"1\",\n              \"-c:v\", \"h264_nvenc\", \"-f\", \"null\", \"-\"], timeout=60)\n    return r.returncode == 0\n\n\ndef ffprobe(p) -> dict:\n    r = _run([\"ffprobe\", \"-v\", \"error\", \"-show_entries\", \"format=duration,size,bit_rate:stream=codec_name,codec_type,width,height,nb_frames,r_frame_rate\",\n              \"-of\", \"json\", str(p)], timeout=60)\n    try:\n        return json.loads(r.stdout)\n    except ValueError:\n        return {\"error\": r.stderr[-300:]}\n\n\n# ---------------------------------------------------------------- context\nclass Context:\n    def __init__(self, bundle: dict, out: Path, work: Path):\n        self.bundle = bundle\n        self.job_id = bundle[\"job_id\"]\n        self.params = bundle.get(\"params\") or {}\n        self.attempt = int(bundle.get(\"attempt\") or 1)\n        self.out, self.work = out, work\n        self.artifacts: list = []\n        self.metrics: dict = {}\n        self.inputs: dict = {}\n        cp = bundle.get(\"checkpoint\") or {}\n        self.resume_state: dict = dict(cp.get(\"state\") or {})\n        self.seq = int(cp.get(\"seq\", 0)) if cp else 0\n        self.last_checkpoint: dict | None = cp or None\n        self._log: list = []\n        (out / \"artifacts\").mkdir(parents=True, exist_ok=True)\n        (out / \"checkpoints\").mkdir(parents=True, exist_ok=True)\n\n    def log(self, msg: str) -> None:\n        line = f\"{time.strftime('%H:%M:%S')} {msg}\"\n        self._log.append(line)\n        print(line, flush=True)\n\n    def artifact(self, path, kind: str = \"other\", name: str | None = None, **provenance) -> dict:\n        src = Path(path)\n        name = name or src.name\n        dst = self.out / \"artifacts\" / name\n        if src.resolve() != dst.resolve():\n            shutil.copyfile(src, dst)\n        a = {\"contract\": \"ArtifactManifest/v1\", \"artifact_id\": \"art_\" + uuid.uuid4().hex[:12], \"kind\": kind, \"name\": name,\n             \"mime\": _mime(name), \"size\": dst.stat().st_size, \"sha256\": sha256_file(dst), \"produced_by_job\": self.job_id,\n             \"provenance\": {\"worker_version\": WORKER_VERSION, \"task\": self.bundle[\"task\"], \"attempt\": self.attempt, **provenance},\n             \"created_at\": time.time()}\n        self.artifacts.append(a)\n        return a\n\n    def write_json_artifact(self, name: str, data: dict, kind: str = \"analysis\") -> dict:\n        p = self.work / name\n        p.write_text(json.dumps(data, indent=1, default=str), encoding=\"utf-8\")\n        return self.artifact(p, kind, name)\n\n    def checkpoint(self, step: str, state: dict) -> dict:\n        self.seq += 1\n        cp = {\"contract\": \"JobCheckpoint/v1\", \"job_id\": self.job_id, \"step\": step, \"seq\": self.seq, \"state\": state,\n              \"artifacts\": [a[\"artifact_id\"] for a in self.artifacts], \"created_at\": time.time()}\n        (self.out / \"checkpoints\" / f\"ckpt_{self.seq:04d}.json\").write_text(json.dumps(cp, indent=1), encoding=\"utf-8\")\n        self.last_checkpoint = cp\n        self.log(f\"checkpoint {self.seq}: {step}\")\n        return cp\n\n    def materialize_inputs(self) -> None:\n        d = self.work / \"inputs\"\n        d.mkdir(parents=True, exist_ok=True)\n        t0, total = time.time(), 0\n        for i in self.bundle.get(\"inputs\") or []:\n            p = d / Path(i[\"name\"]).name\n            if i.get(\"b64\"):\n                p.write_bytes(base64.b64decode(i[\"b64\"]))\n            elif i.get(\"url\"):\n                download(i[\"url\"], p, int(i.get(\"max_bytes\") or 2 * 2 ** 30))\n            elif i.get(\"dataset_file\"):\n                # staged by the control plane as a PRIVATE Kaggle dataset attached to this kernel (no token on the worker)\n                hits = sorted(Path(\"/kaggle/input\").rglob(Path(i[\"dataset_file\"]).name)) if Path(\"/kaggle/input\").exists() else []\n                if not hits:\n                    raise ValueError(f\"input {i['name']} not found under /kaggle/input (dataset not attached?)\")\n                p = hits[0]\n            else:\n                raise ValueError(f\"input {i['name']} has neither b64, url nor dataset_file\")\n            if i.get(\"sha256\") and sha256_file(p) != i[\"sha256\"]:\n                raise ValueError(f\"input {i['name']} checksum mismatch\")\n            total += p.stat().st_size\n            self.inputs[i[\"name\"]] = p\n        self.metrics[\"input_bytes\"] = total\n        self.metrics[\"input_fetch_s\"] = round(time.time() - t0, 3)\n\n\ndef download(url: str, dest: Path, max_bytes: int = 2 * 2 ** 30) -> Path:\n    if not url.startswith(\"https://\"):\n        raise ValueError(\"only https:// inputs are fetched\")\n    req = urllib.request.Request(url, headers={\"User-Agent\": f\"nexus-worker/{WORKER_VERSION}\"})\n    n = 0\n    with urllib.request.urlopen(req, timeout=60) as r, open(dest, \"wb\") as f:  # noqa: S310 - https only, size-capped\n        while True:\n            b = r.read(1 << 20)\n            if not b:\n                break\n            n += len(b)\n            if n > max_bytes:\n                raise ValueError(f\"input exceeds {max_bytes} bytes\")\n            f.write(b)\n    return dest\n\n\ndef _torch():\n    try:\n        import torch\n        return torch\n    except Exception:  # noqa: BLE001\n        return None\n\n\ndef hardware() -> dict:\n    t = _torch()\n    hw = {\"python\": platform.python_version(), \"platform\": platform.platform(), \"cpus\": os.cpu_count(), **_ram(), \"gpus\": gpu_info(),\n          \"torch\": getattr(t, \"__version__\", None), \"cuda\": None, \"ffmpeg\": None}\n    if t is not None and t.cuda.is_available():\n        hw[\"cuda\"] = t.version.cuda\n        hw[\"torch_devices\"] = [{\"name\": t.cuda.get_device_name(i), \"vram_gb\": round(t.cuda.get_device_properties(i).total_memory / 2 ** 30, 2)}\n                               for i in range(t.cuda.device_count())]\n    if shutil.which(\"ffmpeg\"):\n        hw[\"ffmpeg\"] = (_run([\"ffmpeg\", \"-version\"], timeout=20).stdout.splitlines() or [\"\"])[0][:120]\n    return hw\n\n\ndef accelerator_label(hw: dict) -> str | None:\n    g = hw.get(\"gpus\") or []\n    if not g:\n        return None\n    return f\"{g[0]['name']} x{len(g)}\" if len(g) > 1 else g[0][\"name\"]\n\n\n# ---------------------------------------------------------------- built-in tasks\ndef _matmul(t, n: int, dtype_name: str, device: str, iters: int = 10) -> dict:\n    dtype = getattr(t, dtype_name)\n    a = t.randn(n, n, device=device, dtype=dtype)\n    b = t.randn(n, n, device=device, dtype=dtype)\n    (a @ b)\n    if device == \"cuda\":\n        t.cuda.synchronize()\n    t0 = time.perf_counter()\n    for _ in range(iters):\n        (a @ b)\n    if device == \"cuda\":\n        t.cuda.synchronize()\n    el = time.perf_counter() - t0\n    return {\"n\": n, \"dtype\": dtype_name, \"device\": device, \"iters\": iters, \"seconds\": round(el, 4), \"tflops\": round(2 * n ** 3 * iters / el / 1e12, 3)}\n\n\n@task(\"probe\")\ndef task_probe(ctx: Context) -> dict:\n    hw = hardware()\n    t = _torch()\n    bench = []\n    if t is not None:\n        if t.cuda.is_available():\n            bench.append(_matmul(t, 4096, \"float16\", \"cuda\", 20))\n            bench.append(_matmul(t, 4096, \"float32\", \"cuda\", 5))\n        bench.append(_matmul(t, 1024, \"float32\", \"cpu\", 3))\n    hw[\"nvenc\"] = nvenc_available()\n    try:\n        urllib.request.urlopen(\"https://www.google.com\", timeout=5).close()  # noqa: S310\n        hw[\"internet\"] = True\n    except Exception:  # noqa: BLE001\n        hw[\"internet\"] = False\n    ctx.write_json_artifact(\"probe.json\", {\"hardware\": hw, \"matmul\": bench, \"worker_version\": WORKER_VERSION})\n    ctx.metrics[\"hardware\"] = hw\n    return {\"matmul\": bench}\n\n\n@task(\"torch_bench\")\ndef task_torch_bench(ctx: Context) -> dict:\n    t = _torch()\n    if t is None:\n        raise RuntimeError(\"torch is not installed on this worker\")\n    dev = \"cuda\" if t.cuda.is_available() else \"cpu\"\n    sizes = ctx.params.get(\"sizes\") or ([1024, 2048, 4096] if dev == \"cuda\" else [512, 1024])\n    rows = []\n    for n in sizes:\n        for dt in ([\"float32\", \"float16\"] if dev == \"cuda\" else [\"float32\"]):\n            rows.append(_matmul(t, int(n), dt, dev, int(ctx.params.get(\"iters\", 10))))\n    ctx.write_json_artifact(\"torch_bench.json\", {\"device\": dev, \"rows\": rows})\n    return {\"matmul\": rows}\n\n\ndef _encode_args(encoder: str) -> list:\n    if encoder == \"h264_nvenc\":\n        return [\"-c:v\", \"h264_nvenc\", \"-preset\", \"p5\", \"-rc\", \"vbr\", \"-cq\", \"23\", \"-b:v\", \"0\"]\n    return [\"-c:v\", \"libx264\", \"-preset\", \"veryfast\", \"-crf\", \"23\"]\n\n\ndef _pick_encoder(ctx: Context) -> str:\n    want = ctx.params.get(\"encoder\", \"auto\")\n    if want == \"x264\":\n        return \"libx264\"\n    ok = nvenc_available()\n    ctx.metrics[\"nvenc_available\"] = ok\n    if want == \"nvenc\" and not ok:\n        raise RuntimeError(\"NVENC requested but not available on this worker\")\n    return \"h264_nvenc\" if ok else \"libx264\"\n\n\ndef _input_video(ctx: Context) -> Path:\n    if ctx.inputs:\n        return next(iter(ctx.inputs.values()))\n    url = ctx.params.get(\"input_url\")\n    if not url:\n        raise ValueError(\"ffmpeg tasks need an input artifact or params.input_url\")\n    p = ctx.work / \"inputs\" / (Path(url.split(\"?\")[0]).name or \"input.mp4\")\n    p.parent.mkdir(parents=True, exist_ok=True)\n    t0 = time.time()\n    download(url, p)\n    ctx.metrics.update(input_bytes=p.stat().st_size, input_fetch_s=round(time.time() - t0, 3), input_url=url)\n    return p\n\n\ndef _ffmpeg(cmd: list, ctx: Context, timeout: float) -> float:\n    t0 = time.time()\n    r = _run(cmd, timeout=timeout)\n    if r.returncode != 0:\n        raise RuntimeError(f\"ffmpeg failed: {r.stderr[-800:]}\")\n    return time.time() - t0\n\n\n@task(\"ffmpeg_transcode\")\ndef task_ffmpeg_transcode(ctx: Context) -> dict:\n    src = _input_video(ctx)\n    enc = _pick_encoder(ctx)\n    out = ctx.work / ctx.params.get(\"output_name\", \"output.mp4\")\n    vf = [\"-vf\", f\"scale={ctx.params['scale']}\"] if ctx.params.get(\"scale\") else []\n    lim = [\"-t\", str(ctx.params[\"max_seconds\"])] if ctx.params.get(\"max_seconds\") else []\n    cmd = [\"ffmpeg\", \"-hide_banner\", \"-y\", \"-i\", str(src), *lim, *vf, *_encode_args(enc), \"-pix_fmt\", \"yuv420p\",\n           \"-c:a\", \"aac\", \"-b:a\", \"128k\", \"-movflags\", \"+faststart\", str(out)]\n    el = _ffmpeg(cmd, ctx, ctx.bundle.get(\"max_runtime_s\") or 3600)\n    info = ffprobe(out)\n    dur = float((info.get(\"format\") or {}).get(\"duration\") or 0)\n    ctx.artifact(out, \"proxy\", encoder=enc, source=ctx.params.get(\"input_url\") or src.name)\n    return {\"encoder\": enc, \"gpu_encode\": enc == \"h264_nvenc\", \"encode_s\": round(el, 3), \"output_duration_s\": dur,\n            \"realtime_factor\": round(dur / el, 2) if el else None, \"output_probe\": info, \"input_probe\": ffprobe(src)}\n\n\n@task(\"chunked_transcode\")\ndef task_chunked_transcode(ctx: Context) -> dict:\n    \"\"\"Transcode N time-chunks of the input; checkpoint after each chunk. A resumed run skips finished chunks.\n\n    params: chunks (default 4), encoder, scale, simulate_loss_after (int: on attempt 1 only, stop after that many chunks).\"\"\"\n    src = _input_video(ctx)\n    enc = _pick_encoder(ctx)\n    n = int(ctx.params.get(\"chunks\", 4))\n    dur = float((ffprobe(src).get(\"format\") or {}).get(\"duration\") or 0)\n    if dur <= 0:\n        raise ValueError(\"input has no duration\")\n    state = {\"chunks_total\": n, \"done\": [], \"chunk_files\": {}, **ctx.resume_state}\n    done = set(int(i) for i in state[\"done\"])\n    skipped = sorted(done)\n    ran = []\n    stop_after = ctx.params.get(\"simulate_loss_after\")\n    vf = [\"-vf\", f\"scale={ctx.params['scale']}\"] if ctx.params.get(\"scale\") else []\n    for i in range(n):\n        if i in done:\n            ctx.log(f\"chunk {i}: already done in an earlier attempt (checkpoint) - skipped\")\n            continue\n        start, length = dur * i / n, dur / n\n        out = ctx.work / f\"chunk_{i:03d}.mp4\"\n        el = _ffmpeg([\"ffmpeg\", \"-hide_banner\", \"-y\", \"-ss\", f\"{start:.3f}\", \"-i\", str(src), \"-t\", f\"{length:.3f}\", *vf,\n                      *_encode_args(enc), \"-pix_fmt\", \"yuv420p\", \"-an\", str(out)], ctx, ctx.bundle.get(\"max_runtime_s\") or 3600)\n        a = ctx.artifact(out, \"proxy\", chunk=i, encoder=enc)\n        ran.append({\"chunk\": i, \"encode_s\": round(el, 3), \"sha256\": a[\"sha256\"]})\n        state[\"done\"] = sorted(done | {i} | {r[\"chunk\"] for r in ran})\n        state[\"chunk_files\"][str(i)] = {\"name\": a[\"name\"], \"sha256\": a[\"sha256\"], \"attempt\": ctx.attempt}\n        ctx.checkpoint(f\"chunk_{i}\", json.loads(json.dumps(state)))\n        if stop_after is not None and ctx.attempt == 1 and len(ran) >= int(stop_after) and len(state[\"done\"]) < n:\n            ctx.metrics.update(chunks_run_this_attempt=[r[\"chunk\"] for r in ran], chunks_skipped=skipped, encoder=enc)\n            raise SimulatedWorkerLoss(f\"simulated worker loss after {len(ran)} chunk(s) (params.simulate_loss_after)\")\n    return {\"encoder\": enc, \"chunks_total\": n, \"chunks_run_this_attempt\": [r[\"chunk\"] for r in ran], \"chunks_skipped\": skipped,\n            \"chunk_runs\": ran, \"input_duration_s\": dur}\n\n\n# ---------------------------------------------------------------- runner\ndef run(bundle: dict, out_dir) -> dict:\n    out = Path(out_dir)\n    out.mkdir(parents=True, exist_ok=True)\n    work = Path(tempfile.mkdtemp(prefix=\"nexus_work_\"))\n    ctx = Context(bundle, out, work)\n    sampler = Sampler()\n    t = _torch()\n    hw = {\"gpus\": gpu_info()}\n    started = time.time()\n    status, error = \"succeeded\", None\n    sampler.start()\n    try:\n        fn = TASKS.get(bundle[\"task\"])\n        if fn is None:\n            raise LookupError(f\"task '{bundle['task']}' is not registered in worker {WORKER_VERSION} (have: {sorted(TASKS)})\")\n        ctx.log(f\"NEXUS worker {WORKER_VERSION}: job {ctx.job_id} task {bundle['task']} attempt {ctx.attempt}\")\n        ctx.materialize_inputs()\n        if t is not None and t.cuda.is_available():\n            t.cuda.reset_peak_memory_stats()\n        extra = fn(ctx) or {}\n        ctx.metrics.update(extra)\n    except SimulatedWorkerLoss as e:\n        status, error = \"lost\", str(e)\n        ctx.log(error)\n    except Exception as e:  # noqa: BLE001 - every failure is reported in result.json\n        status, error = \"failed\", f\"{type(e).__name__}: {e}\"\n        ctx.log(traceback.format_exc()[-2000:])\n    finally:\n        sampler.halt.set()\n        sampler.join(timeout=3)\n    finished = time.time()\n    m = ctx.metrics\n    m.update(sampler.summary())\n    m.update(_ram())\n    try:\n        import resource\n        m[\"peak_rss_mb\"] = round(max(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss, resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss) / 1024, 1)\n    except Exception:  # noqa: BLE001\n        pass\n    if t is not None and t.cuda.is_available():\n        m[\"peak_vram_allocated_mb\"] = round(max(t.cuda.max_memory_allocated(i) for i in range(t.cuda.device_count())) / 2 ** 20, 1)\n    m.setdefault(\"model_download_bytes\", 0)\n    m[\"gpus\"] = hw[\"gpus\"]\n    m[\"output_bytes\"] = sum(a[\"size\"] for a in ctx.artifacts)\n    m[\"worker_version\"] = WORKER_VERSION\n    m[\"task_s\"] = round(finished - started, 3)\n    res = {\"contract\": \"WorkerExecutionResult/v1\", \"job_id\": ctx.job_id, \"provider\": bundle.get(\"provider\", \"local\"),\n           \"connection_id\": bundle.get(\"connection_id\", \"local\"), \"status\": status, \"started_at\": started, \"finished_at\": finished,\n           \"duration_s\": round(finished - started, 3), \"accelerator\": accelerator_label(hw), \"metrics\": m, \"artifacts\": ctx.artifacts,\n           \"log_tail\": \"\\n\".join(ctx._log)[-4000:], \"error\": error, \"checkpoint\": ctx.last_checkpoint}\n    (out / \"result.json\").write_text(json.dumps(res, indent=1, default=str), encoding=\"utf-8\")\n    shutil.rmtree(work, ignore_errors=True)\n    return res\n\n\ndef main(argv=None) -> int:\n    import argparse\n    ap = argparse.ArgumentParser(description=\"NEXUS remote worker\")\n    ap.add_argument(\"--bundle\", help=\"job bundle JSON file (default: the bundle embedded in this script)\")\n    ap.add_argument(\"--out\", help=\"output directory (default /kaggle/working on Kaggle, else ./nexus_out)\")\n    a = ap.parse_args(argv)\n    if a.bundle:\n        bundle = json.loads(Path(a.bundle).read_text(encoding=\"utf-8\"))\n    elif _EMBEDDED_BUNDLE_B64:\n        bundle = json.loads(base64.b64decode(_EMBEDDED_BUNDLE_B64))\n    else:\n        ap.error(\"no --bundle and no embedded bundle\")\n    out = a.out or (\"/kaggle/working\" if Path(\"/kaggle/working\").is_dir() else \"nexus_out\")\n    res = run(bundle, out)\n    print(json.dumps({\"status\": res[\"status\"], \"duration_s\": res[\"duration_s\"], \"artifacts\": len(res[\"artifacts\"])}))\n    return 0  # result.json carries the status; exit 0 so the outputs are always kept and retrievable\n\n\n# ---- task file a2_render_steps.py\n# ruff: noqa: F821\n# Account 2 task (nexus/timeline/remote_render.py compiles the steps). Appended to Account 1's nexus_worker.py when a\n# worker script is built: `task`, `Context`, `ffprobe` and `_ffmpeg` are that script's globals.\n\n\n@task(\"a2_render_steps\")\ndef task_a2_render_steps(ctx: Context) -> dict:\n    \"\"\"Run Account 2's compiled FFmpeg steps. params: steps (list of argument lists with {in:<name>} / {work}\n    placeholders), output (file name in {work}), expect {width,height,fps,duration}. One checkpoint per finished step.\"\"\"\n    import time as _t\n    steps = ctx.params[\"steps\"]\n    done = int(ctx.resume_state.get(\"steps_done\", 0))\n    work = str(ctx.work)\n\n    def sub(a):\n        a = str(a).replace(\"{work}\", work)\n        if a.startswith(\"{in:\") and a.endswith(\"}\"):\n            name = a[4:-1]\n            if name not in ctx.inputs:\n                raise ValueError(f\"input {name!r} was not delivered to the worker (have {sorted(ctx.inputs)})\")\n            return str(ctx.inputs[name])\n        return a\n\n    t0 = _t.time()\n    for i, st in enumerate(steps):\n        if i < done:\n            ctx.log(f\"step {i}: done in an earlier attempt - skipped\")\n            continue\n        _ffmpeg([\"ffmpeg\", \"-hide_banner\", \"-nostdin\", \"-y\", *[sub(a) for a in st]], ctx, ctx.bundle.get(\"max_runtime_s\") or 3600)\n        ctx.checkpoint(f\"step_{i}\", {\"steps_done\": i + 1})\n    out = ctx.work / ctx.params.get(\"output\", \"master.mp4\")\n    info = ffprobe(out)\n    v = next((s for s in info.get(\"streams\", []) if s.get(\"codec_type\") == \"video\"), {})\n    dur = float((info.get(\"format\") or {}).get(\"duration\") or 0)\n    exp = ctx.params.get(\"expect\") or {}\n    ok = (not exp or (v.get(\"width\") == exp.get(\"width\") and v.get(\"height\") == exp.get(\"height\")\n                      and abs(dur - float(exp.get(\"duration\", dur))) <= 2.0 / max(1, int(exp.get(\"fps\", 25)))))\n    ctx.artifact(out, \"master\", producer=\"account2\", task=\"a2_render_steps\")\n    return {\"steps\": len(steps), \"steps_skipped\": done, \"render_s\": round(_t.time() - t0, 3), \"output_duration_s\": dur,\n            \"width\": v.get(\"width\"), \"height\": v.get(\"height\"), \"matches_expectation\": ok}\n\n\n# ---- task file a2_wan_video.py\n# ruff: noqa: F821\n# Wan 2.2 TI2V-5B text-to-video / image-to-video on a GPU worker (Kaggle T4 x2 verified; see\n# docs/results/wan22_5b/). Appended to Account 1's nexus_worker.py: `task`, `Context`, `_torch`, `ffprobe`, `_run`\n# are that script's globals.\n#\n# Execution strategy (measured on Kaggle T4 x2, not assumed): `enable_model_cpu_offload()` keeps modules on ONE GPU.\n# Instead: (1) the UMT5-XXL text encoder (~11 GB, BF16 - emulated on T4, probed with a real matmul first) encodes every\n# prompt on cuda:1 and is then freed; (2) the 5B transformer (FP16: T4/sm_75 has no native BF16; BF16 on sm_80+) is\n# layer-sharded, blocks 0-14 on cuda:0 and 15-29 on cuda:1; (3) the VAE (FP32) lives on cuda:1: it encodes the I2V\n# image there (latents handed to cuda:0) and decodes there, untiled when it fits, else with our first-chunk-aware spatial tiling (diffusers 0.35.2's\n# tiled_decode drops first_chunk and unpatchify for the Wan 2.2 VAE and crashes). NaN/Inf, black or flat output is a\n# failure and is never exported. No silent fallback to the 1.3B model.\n\n_WAN_REPOS = {\"wan21-t2v-1.3b\": (\"Wan-AI/Wan2.1-T2V-1.3B-Diffusers\", \"0fad780a534b6463e45facd96134c9f345acfa5b\"),\n              \"wan22-ti2v-5b\": (\"Wan-AI/Wan2.2-TI2V-5B-Diffusers\", \"b8fff7315c768468a5333511427288870b2e9635\")}\n_WAN_DIFFUSERS = \"0.35.2\"   # first stable line with WanPipeline expand_timesteps (TI2V); pinned for reproducibility\n_WAN_NEG = (\"blurry, low quality, worst quality, jpeg artifacts, static, still image, frozen frame, distorted, deformed, \"\n            \"disfigured, extra limbs, watermark, text, subtitles, logo, overexposed, underexposed\")\n\n\ndef _wan_env(torch) -> dict:\n    n = torch.cuda.device_count()\n    gpus = []\n    for i in range(n):\n        p = torch.cuda.get_device_properties(i)\n        gpus.append({\"index\": i, \"name\": p.name, \"vram_gb\": round(p.total_memory / 2 ** 30, 2), \"cc\": f\"{p.major}.{p.minor}\"})\n    bf16_native = n > 0 and torch.cuda.get_device_capability(0)[0] >= 8\n    bf16_works = False\n    if n:\n        try:\n            a = torch.randn(256, 256, device=f\"cuda:{n - 1}\", dtype=torch.bfloat16)\n            bf16_works = bool(torch.isfinite(a @ a).all().item())\n        except Exception:  # noqa: BLE001\n            bf16_works = False\n    vers = {}\n    for m in (\"torch\", \"diffusers\", \"transformers\", \"accelerate\", \"safetensors\", \"huggingface_hub\"):\n        try:\n            vers[m] = __import__(m).__version__\n        except Exception:  # noqa: BLE001\n            vers[m] = None\n    vers[\"cuda\"] = torch.version.cuda\n    return {\"gpu_count\": n, \"gpus\": gpus, \"bf16_native\": bf16_native, \"bf16_matmul_works\": bf16_works, \"versions\": vers}\n\n\ndef _wan_ensure_diffusers(ctx) -> None:\n    try:\n        import diffusers\n        if diffusers.__version__ == _WAN_DIFFUSERS:\n            return\n    except Exception:  # noqa: BLE001\n        pass\n    ctx.log(f\"installing diffusers=={_WAN_DIFFUSERS} (pinned)\")\n    r = _run([sys.executable, \"-m\", \"pip\", \"install\", \"-q\", f\"diffusers=={_WAN_DIFFUSERS}\", \"ftfy\"], timeout=900)\n    if r.returncode != 0:\n        raise RuntimeError(f\"pip install diffusers=={_WAN_DIFFUSERS} failed: {r.stderr[-400:]}\")\n    for k in [k for k in sys.modules if k == \"diffusers\" or k.startswith(\"diffusers.\")]:\n        del sys.modules[k]\n\n\nclass _GpuPeak(threading.Thread):\n    \"\"\"Per-GPU utilisation / used-memory peaks from nvidia-smi (the worker's Sampler keeps only a pooled summary).\"\"\"\n\n    def __init__(self, every=2.0):\n        super().__init__(daemon=True)\n        self.every, self.halt, self.rows = every, threading.Event(), []\n\n    def run(self):\n        while not self.halt.wait(self.every):\n            try:\n                r = _run([\"nvidia-smi\", \"--query-gpu=index,utilization.gpu,memory.used\", \"--format=csv,noheader,nounits\"], timeout=5)\n                self.rows.append([[float(x) for x in ln.split(\",\")] for ln in r.stdout.strip().splitlines() if ln.strip()])\n            except Exception:  # noqa: BLE001\n                pass\n\n    def summary(self, n):\n        out = []\n        for i in range(n):\n            u = [r[i][1] for r in self.rows if len(r) > i]\n            m = [r[i][2] for r in self.rows if len(r) > i]\n            out.append({\"index\": i, \"util_max\": max(u) if u else None, \"util_mean\": round(sum(u) / len(u), 1) if u else None,\n                        \"smi_mem_used_max_mb\": max(m) if m else None})\n        return out\n\n\ndef _wan_quality(frames) -> dict:\n    \"\"\"Motion / emptiness checks on the decoded frames (uint8 HxWx3 numpy arrays).\"\"\"\n    import numpy as np\n    arr = np.stack([np.asarray(f, dtype=np.float32) for f in frames])\n    luma = arr.mean(axis=(1, 2, 3))\n    diffs = np.abs(arr[1:] - arr[:-1]).mean(axis=(1, 2, 3)) if len(arr) > 1 else np.zeros(1)\n    return {\"frames\": int(len(arr)), \"mean_luma\": round(float(luma.mean()), 2), \"min_frame_luma\": round(float(luma.min()), 2),\n            \"mean_frame_std\": round(float(arr.std(axis=(1, 2, 3)).mean()), 2),\n            \"mean_abs_frame_diff\": round(float(diffs.mean()), 3), \"max_abs_frame_diff\": round(float(diffs.max()), 3),\n            \"first_last_diff\": round(float(np.abs(arr[-1] - arr[0]).mean()), 3),\n            \"static_pairs\": int((diffs < 0.5).sum()), \"black\": bool(luma.max() < 8), \"flat\": bool(arr.std() < 2)}\n\n\ndef _wan_write_mp4(frames, path, fps: int) -> None:\n    import numpy as np\n    h, w = np.asarray(frames[0]).shape[:2]\n    p = subprocess.Popen([\"ffmpeg\", \"-v\", \"error\", \"-y\", \"-f\", \"rawvideo\", \"-pix_fmt\", \"rgb24\", \"-s\", f\"{w}x{h}\", \"-r\", str(fps),\n                          \"-i\", \"-\", \"-c:v\", \"libx264\", \"-preset\", \"slow\", \"-crf\", \"16\", \"-pix_fmt\", \"yuv420p\",\n                          \"-movflags\", \"+faststart\", str(path)], stdin=subprocess.PIPE)\n    for f in frames:\n        p.stdin.write(np.ascontiguousarray(np.asarray(f, dtype=np.uint8)).tobytes())\n    p.stdin.close()\n    if p.wait() != 0:\n        raise RuntimeError(\"ffmpeg encode failed\")\n\n\ndef _wan_to(obj, dev):\n    import torch\n    if isinstance(obj, torch.Tensor):\n        return obj.to(dev)\n    if isinstance(obj, (tuple, list)):\n        return type(obj)(_wan_to(o, dev) for o in obj)\n    if isinstance(obj, dict):\n        return {k: _wan_to(v, dev) for k, v in obj.items()}\n    return obj\n\n\ndef _wan_shard(tr, dev_main, dev_aux) -> dict:\n    \"\"\"Genuine layer sharding of the 5B transformer: the second half of its blocks lives on dev_aux. A pre-hook moves\n    each block's inputs to its device; the last block's output comes back to dev_main for the final norm/projection.\"\"\"\n    blocks = tr.blocks\n    cut = len(blocks) // 2\n    for i, b in enumerate(blocks):\n        dev = dev_main if i < cut else dev_aux\n        b.to(dev)\n        b.register_forward_pre_hook(lambda m, a, kw, _d=dev: (_wan_to(a, _d), _wan_to(kw, _d)), with_kwargs=True)\n    blocks[-1].register_forward_hook(lambda m, a, out: _wan_to(out, dev_main))\n    return {\"blocks_on_main\": cut, \"blocks_on_aux\": len(blocks) - cut}\n\n\ndef _wan_tiled_decode(vae, z, tile: int = 256, stride: int = 192):\n    \"\"\"Spatially tiled Wan 2.2 VAE decode that keeps the causal first-chunk handling and the patch_size unpatchify of\n    AutoencoderKLWan._decode (diffusers 0.35.2 tiled_decode omits both: measured crash on Kaggle 2026-11-13). Tiles are\n    collected on the CPU and blended with the VAE's own blend_v/blend_h; returns a CPU float tensor in [-1, 1].\"\"\"\n    import torch\n    from diffusers.models.autoencoders.autoencoder_kl_wan import unpatchify\n    # decoder upsampling x patch unpatchify (Wan 2.2: 8 x 2 = 16 pixels per latent; spatial_compression_ratio is 8 alone)\n    r = vae.spatial_compression_ratio * (vae.config.patch_size or 1)\n    tl, sl = tile // r, stride // r\n    _, _, T, H, W = z.shape\n    blend = tile - stride\n    rows = []\n    for i in range(0, H, sl):\n        row = []\n        for j in range(0, W, sl):\n            vae.clear_cache()\n            x = vae.post_quant_conv(z[:, :, :, i:i + tl, j:j + tl])\n            outs = []\n            for k in range(T):\n                vae._conv_idx = [0]\n                outs.append(vae.decoder(x[:, :, k:k + 1], feat_cache=vae._feat_map, feat_idx=vae._conv_idx, first_chunk=(k == 0)))\n            o = torch.cat(outs, 2)\n            if vae.config.patch_size is not None:\n                o = unpatchify(o, patch_size=vae.config.patch_size)\n            row.append(o.clamp(-1, 1).float().cpu())\n            del outs, o, x\n        rows.append(row)\n    vae.clear_cache()\n    res = []\n    for i, row in enumerate(rows):\n        rr = []\n        for j, t in enumerate(row):\n            if i > 0:\n                t = vae.blend_v(rows[i - 1][j], t, blend)\n            if j > 0:\n                t = vae.blend_h(row[j - 1], t, blend)\n            rr.append(t[:, :, :, :stride, :stride])\n        res.append(torch.cat(rr, dim=-1))\n    return torch.cat(res, dim=3)[:, :, :, :H * r, :W * r]\n\n\n@task(\"a2_wan_video\")\ndef task_a2_wan_video(ctx: Context) -> dict:\n    \"\"\"params: model (catalogue id), runs: [{mode: t2v|i2v, prompt, image_url?, width, height, frames, fps, steps,\n    guidance, seed}] (or a single run as prompt + settings, the original Account 2 shape). One MP4 artifact per run plus\n    wan_benchmark.json. Refuses to run without CUDA: a CPU stand-in would be mislabelled as generated video.\"\"\"\n    import time as _t\n    torch = _torch()\n    if torch is None or not torch.cuda.is_available():\n        raise RuntimeError(\"RESOURCE_EXHAUSTED: a2_wan_video needs a CUDA GPU; refusing to produce a CPU stand-in\")\n    os.environ.setdefault(\"HF_HOME\", \"/tmp/hf_home\")      # weights never land in the job's output directory\n    os.environ.setdefault(\"HF_HUB_ENABLE_HF_TRANSFER\", \"0\")\n    os.environ.setdefault(\"PYTORCH_CUDA_ALLOC_CONF\", \"expandable_segments:True\")\n    _wan_ensure_diffusers(ctx)\n    env = _wan_env(torch)\n    ctx.log(f\"wan env: {json.dumps(env)}\")\n    repo, rev = _WAN_REPOS[ctx.params[\"model\"]]\n    rev = ctx.params.get(\"revision\") or rev\n    runs = ctx.params.get(\"runs\") or [{\"mode\": \"t2v\", \"prompt\": ctx.params[\"prompt\"], **(ctx.params.get(\"settings\") or {})}]\n    done = dict(ctx.resume_state.get(\"done\") or {})\n    n = env[\"gpu_count\"]\n    dev_main = torch.device(\"cuda:0\")\n    dev_aux = torch.device(f\"cuda:{n - 1}\")\n    tdtype = {\"fp16\": torch.float16, \"bf16\": torch.bfloat16}.get(ctx.params.get(\"dtype\") or (\"bf16\" if env[\"bf16_native\"] else \"fp16\"))\n    te_mode = ctx.params.get(\"text_encoder\") or (\"gpu-bf16\" if env[\"bf16_matmul_works\"] and n > 1 else \"cpu-fp32\")\n\n    import diffusers\n    from diffusers import AutoencoderKLWan, WanImageToVideoPipeline, WanPipeline, WanTransformer3DModel\n    from transformers import AutoTokenizer, UMT5EncoderModel\n\n    class _T2V(WanPipeline):\n        @property\n        def _execution_device(self):\n            return dev_main\n\n    class _I2V(WanImageToVideoPipeline):\n        @property\n        def _execution_device(self):\n            return dev_main\n\n    peak = _GpuPeak()\n    peak.start()\n    t0 = _t.time()\n    from huggingface_hub import snapshot_download\n    local = snapshot_download(repo, revision=rev, allow_patterns=[\"model_index.json\", \"scheduler/*\", \"text_encoder/*\", \"tokenizer/*\",\n                                                                  \"transformer/*\", \"vae/*\", \"examples/*\"])\n    dl_s = _t.time() - t0\n    ctx.log(f\"snapshot {repo}@{rev} in {dl_s:.0f}s\")\n    t1 = _t.time()\n    tok = AutoTokenizer.from_pretrained(local, subfolder=\"tokenizer\")\n    if te_mode == \"gpu-bf16\":\n        te = UMT5EncoderModel.from_pretrained(local, subfolder=\"text_encoder\", torch_dtype=torch.bfloat16, low_cpu_mem_usage=True).to(dev_aux)\n    else:\n        te = UMT5EncoderModel.from_pretrained(local, subfolder=\"text_encoder\", torch_dtype=torch.float32, low_cpu_mem_usage=True)\n    te.eval()\n    tr = WanTransformer3DModel.from_pretrained(local, subfolder=\"transformer\", torch_dtype=tdtype, low_cpu_mem_usage=True).to(dev_main)\n    vae = AutoencoderKLWan.from_pretrained(local, subfolder=\"vae\", torch_dtype=torch.float32).to(dev_main)\n    load_s = _t.time() - t1\n    ctx.log(f\"loaded in {load_s:.0f}s: transformer {tdtype} on {dev_main}, text encoder {te_mode}, vae fp32\")\n    common = dict(tokenizer=tok, text_encoder=te, transformer=tr, vae=vae,\n                  scheduler=diffusers.UniPCMultistepScheduler.from_pretrained(local, subfolder=\"scheduler\"))\n    t2v = _T2V(**common, expand_timesteps=True)\n    i2v = _I2V(**common, image_encoder=None, image_processor=None, expand_timesteps=True)\n    te_dev = dev_aux if te_mode == \"gpu-bf16\" else torch.device(\"cpu\")\n    embeds, te_s = {}, {}\n    for k, r in enumerate(runs):\n        if f\"run{k}\" in done:\n            continue\n        te_t = _t.time()\n        with torch.no_grad():\n            pe, ne = t2v.encode_prompt(r[\"prompt\"], r.get(\"negative_prompt\", _WAN_NEG), do_classifier_free_guidance=float(r.get(\"guidance\", 5.0)) > 1.0,\n                                       max_sequence_length=512, device=te_dev, dtype=te.dtype)\n        embeds[k] = (pe.to(\"cpu\"), ne.to(\"cpu\") if ne is not None else None)\n        te_s[k] = round(_t.time() - te_t, 1)\n    # the text encoder is not needed again: free its ~11 GB for the transformer shard and the VAE decode on cuda:1\n    t2v.text_encoder = i2v.text_encoder = None\n    common.clear()          # the constructor kwargs held a second reference to the encoder (measured: 14.1 GB stayed on cuda:1)\n    del te\n    import gc\n    gc.collect()\n    torch.cuda.empty_cache()\n    ctx.log(f\"text encoder freed: cuda:{dev_aux.index} free {torch.cuda.mem_get_info(dev_aux)[0] / 2 ** 30:.1f} GB\")\n    if n > 1:\n        # the VAE lives on cuda:1 for the whole job; the I2V image encode runs there and its latent distribution is\n        # handed back to cuda:0 (measured: an fp32 720p encode on cuda:0 left ~2 GB of allocator cache and the first\n        # I2V denoising step ran out of memory, rjob_5b6d09efb6d1)\n        from diffusers.models.autoencoders.vae import DiagonalGaussianDistribution\n        from diffusers.models.modeling_outputs import AutoencoderKLOutput\n        vae.to(dev_aux)\n        _enc = vae.encode\n\n        def _encode_on_aux(x, return_dict=True):\n            d = DiagonalGaussianDistribution(_enc(x.to(dev_aux)).latent_dist.parameters.to(dev_main))\n            torch.cuda.empty_cache()\n            return AutoencoderKLOutput(latent_dist=d) if return_dict else (d,)\n        vae.encode = _encode_on_aux\n        torch.cuda.empty_cache()\n    shard = None\n    if n > 1 and ctx.params.get(\"shard\", True):\n        shard = _wan_shard(tr, dev_main, dev_aux)\n        torch.cuda.empty_cache()\n        ctx.log(f\"transformer sharded {shard}: free cuda:0 {torch.cuda.mem_get_info(dev_main)[0] / 2 ** 30:.1f} GB, \"\n                f\"cuda:{dev_aux.index} {torch.cuda.mem_get_info(dev_aux)[0] / 2 ** 30:.1f} GB\")\n    results = []\n    for k, r in enumerate(runs):\n        key = f\"run{k}\"\n        if key in done:\n            results.append(done[key])\n            ctx.log(f\"{key}: already done (resumed)\")\n            continue\n        mode = r.get(\"mode\", \"t2v\")\n        W, H, F = int(r.get(\"width\", 1280)), int(r.get(\"height\", 704)), int(r.get(\"frames\", 121))\n        steps, gs, seed, fps = int(r.get(\"steps\", 50)), float(r.get(\"guidance\", 5.0)), int(r.get(\"seed\", 42)), int(r.get(\"fps\", 24))\n        for i in range(n):\n            torch.cuda.reset_peak_memory_stats(i)\n        pe, ne = embeds[k]\n        pe, ne = pe.to(dev_main, tdtype), (ne.to(dev_main, tdtype) if ne is not None else None)\n        vae.to(dev_main if n == 1 else dev_aux)\n        g = torch.Generator(device=dev_main).manual_seed(seed)\n        g_t = _t.time()\n        step_times = []\n\n        def _cb(pipe, i, t, kw, _st=step_times):\n            _st.append(_t.time())\n            return kw\n        kw = dict(prompt_embeds=pe, negative_prompt_embeds=ne, height=H, width=W, num_frames=F, num_inference_steps=steps,\n                  guidance_scale=gs, generator=g, output_type=\"latent\", callback_on_step_end=_cb)\n        image_info = None\n        if mode == \"i2v\":\n            from diffusers.utils import load_image\n            src = r.get(\"image_url\") or str(Path(local) / \"examples\" / \"i2v_input.JPG\")\n            img = load_image(src).convert(\"RGB\")\n            image_info = {\"source\": r.get(\"image_url\") or f\"{repo}@{rev}:examples/i2v_input.JPG\", \"size\": list(img.size)}\n            with torch.no_grad():\n                lat = i2v(image=img, **kw).frames\n        else:\n            with torch.no_grad():\n                lat = t2v(**kw).frames\n        gen_s = _t.time() - g_t\n        if not torch.isfinite(lat).all():\n            raise RuntimeError(f\"{key}: non-finite latents with transformer dtype {tdtype} (precision overflow); not exported\")\n        # decode on the auxiliary GPU (FP32; tiled above ~1.5x 672x384 pixels)\n        d_t = _t.time()\n        vae.to(dev_aux)\n        free_aux = torch.cuda.mem_get_info(dev_aux)[0] / 2 ** 30\n        with torch.no_grad():\n            z = lat.to(dev_aux, torch.float32)\n            mean = torch.tensor(vae.config.latents_mean).view(1, vae.config.z_dim, 1, 1, 1).to(z)\n            inv_std = 1.0 / torch.tensor(vae.config.latents_std).view(1, vae.config.z_dim, 1, 1, 1).to(z)\n            zz = z / inv_std + mean\n            tiled = r.get(\"decode\", \"auto\") == \"tiled\" or (r.get(\"decode\", \"auto\") == \"auto\" and W * H > 672 * 384 * 1.5)\n            video = _wan_tiled_decode(vae, zz) if tiled else vae.decode(zz, return_dict=False)[0].float().cpu()\n            decode_check = None\n            if r.get(\"decode_check\"):   # same latents both ways: proves the tiled decode against the reference decode\n                other = vae.decode(zz, return_dict=False)[0].float().cpu() if tiled else _wan_tiled_decode(vae, zz)\n                mse = float(((video - other) ** 2).mean())\n                decode_check = {\"psnr_db\": round(10 * __import__(\"math\").log10(4.0 / max(mse, 1e-12)), 2), \"mse\": mse}\n            frames = t2v.video_processor.postprocess_video(video, output_type=\"np\")[0]\n        dec_s = _t.time() - d_t\n        frames = [(f * 255).round().clip(0, 255).astype(\"uint8\") for f in frames]\n        q = _wan_quality(frames)\n        if q[\"black\"] or q[\"flat\"]:\n            raise RuntimeError(f\"{key}: decoded video is black/flat {q}; not exported\")\n        out = ctx.work / f\"wan22_5b_{mode}_{W}x{H}_{F}f_{key}.mp4\"\n        _wan_write_mp4(frames, out, fps)\n        probe = ffprobe(out)\n        vram = [{\"index\": i, \"peak_allocated_mb\": round(torch.cuda.max_memory_allocated(i) / 2 ** 20, 1),\n                 \"peak_reserved_mb\": round(torch.cuda.max_memory_reserved(i) / 2 ** 20, 1)} for i in range(n)]\n        sp = [b - a for a, b in zip([g_t] + step_times[:-1], step_times)]\n        res = {\"run\": key, \"mode\": mode, \"prompt\": r[\"prompt\"], \"image\": image_info, \"width\": W, \"height\": H, \"frames\": F, \"fps\": fps,\n               \"steps\": steps, \"guidance\": gs, \"seed\": seed, \"scheduler\": \"UniPCMultistepScheduler\",\n               \"text_encode_s\": te_s.get(k), \"generate_s\": round(gen_s, 1), \"decode_s\": round(dec_s, 1),\n               \"s_per_step_mean\": round(sum(sp) / len(sp), 2) if sp else None, \"aux_free_gb_before_decode\": round(free_aux, 2),\n               \"decode\": \"tiled (own, first-chunk aware)\" if tiled else \"untiled\", \"decode_check\": decode_check, \"vram\": vram, \"quality\": q, \"ffprobe\": probe}\n        a = ctx.artifact(out, \"source\", classification=\"generated-video\", model=ctx.params[\"model\"], repo=repo, revision=rev, mode=mode,\n                         gpu=env[\"gpus\"][0][\"name\"], prompt=r[\"prompt\"], seed=seed, steps=steps)\n        res[\"artifact\"] = {\"name\": a[\"name\"], \"sha256\": a[\"sha256\"], \"size\": a[\"size\"]}\n        results.append(res)\n        done[key] = res\n        ctx.checkpoint(f\"wan-{key}\", {\"done\": done})\n        ctx.log(f\"{key}: {mode} {W}x{H}x{F} {steps} steps gen {gen_s:.0f}s decode {dec_s:.0f}s motion {q['mean_abs_frame_diff']}\")\n        vae.to(dev_main if n == 1 else dev_aux)\n        torch.cuda.empty_cache()\n    peak.halt.set()\n    peak.join(timeout=3)\n    bench = {\"model\": ctx.params[\"model\"], \"repo\": repo, \"revision\": rev, \"licence\": \"apache-2.0\", \"diffusers_pinned\": _WAN_DIFFUSERS,\n             \"env\": env, \"strategy\": {\"transformer\": f\"{tdtype}, \" + (f\"blocks split {shard} across {dev_main}/{dev_aux}\" if shard else f\"on {dev_main}\"), \"text_encoder\": te_mode + (f\" on {dev_aux}\" if te_mode == \"gpu-bf16\" else \"\"),\n                                      \"vae\": f\"fp32 on {dev_aux} for I2V encode (latents handed to {dev_main}) and decode (untiled when it fits, else own first-chunk-aware tiling)\", \"cpu_offload\": False},\n             \"download_s\": round(dl_s, 1), \"load_s\": round(load_s, 1), \"runs\": results, \"per_gpu\": peak.summary(n)}\n    ctx.write_json_artifact(\"wan_benchmark.json\", bench)\n    return {\"model\": ctx.params[\"model\"], \"gpu\": env[\"gpus\"][0][\"name\"], \"gpu_count\": n, \"load_s\": round(load_s, 1),\n            \"download_s\": round(dl_s, 1), \"runs_ok\": len(results), \"per_gpu\": peak.summary(n)}\n\n\n# ---- task file batch_llm.py\n# ruff: noqa: F821\n\"\"\"batch_llm: bounded, temporary batch inference over a JSONL of prompts (Account 3 request A1-3).\n\nOne job = one model, one finite list of prompts, one run. The model is loaded inside the worker, every prompt is\nanswered, the outputs are written as verified artifacts and the process exits: there is NO serving endpoint, no open\nport, no background process (Kaggle does not allow persistent serving). Routing (nexus/cloud/compute/tasks.py) restricts\nthe task to the authorised Kaggle GPU worker; the owner's own PC is never chosen, and real model engines refuse to\ndownload weights anywhere but a Kaggle kernel unless NEXUS_BATCH_LLM_ALLOW_HERE=1 is set by the owner on that machine.\n\nInput items (input JSONL artifact, one object per line, or params.items for small inline lists):\n    {\"id\": \"q1\", \"task\": \"summarization\", \"system\": \"...\", \"prompt\": \"...\", \"max_tokens\": 256}\nOutput rows (batch_llm_part_NNNN.aK.jsonl per part; the control plane joins them into batch_llm_results.jsonl):\n    {\"id\", \"text\", \"usage\": {\"prompt_tokens\", \"completion_tokens\"}, \"finish_reason\", \"latency_s\", \"error\"}\n\nparams:\n    model             HF repo id (required), e.g. \"Qwen/Qwen2.5-0.5B-Instruct\"; model_revision optional (pins a commit)\n    model_licence     recorded in provenance and the summary (default \"unverified\"; Account 3 checks commercial use)\n    engine            \"transformers\" (default) | \"vllm\" (offline LLM.generate, only if already installed) | \"echo\"\n                      (\"echo\" loads no model: deterministic test engine; its results are labelled simulated)\n    output_format     \"jsonl\" (default) | \"json\"\n    max_items         cap on items processed (default 500, hard cap 5000); extra items are refused, not truncated silently\n    max_new_tokens    per-item cap (default 256, hard cap 4096); an item's own max_tokens is clipped to it\n    max_prompt_chars  longer prompts are reported as item errors (default 16000)\n    batch_size        prompts per generate call (default 8); part_size items per part/checkpoint (default 32)\n    max_model_gb      refuse a model whose weight files exceed this (default 8.0); checked BEFORE downloading\n    temperature       0 = greedy (default); seed (default 0)\n    chat_template_kwargs  passed to apply_chat_template (e.g. {\"enable_thinking\": false} for Qwen3)\n    time_budget_s     stop starting new parts after this (default 85 % of max_runtime_s); the job then resumes from\n                      its last checkpoint in a new bounded attempt (counts against max_retries)\n    simulate_loss_after_parts  tests only: on attempt 1, stop after that many parts\n\"\"\"\n\nBATCH_LLM_HARD_MAX_ITEMS = 5000\nBATCH_LLM_HARD_MAX_TOKENS = 4096\n\n\nclass BatchLLMBudgetReached(SimulatedWorkerLoss):\n    \"\"\"Time budget reached with items left: reported as 'lost' so the dispatcher resumes from the last checkpoint.\"\"\"\n\n\ndef _bl_items(ctx) -> list:\n    if ctx.params.get(\"items\") is not None:\n        raw = list(ctx.params[\"items\"])\n    elif ctx.inputs:\n        name = ctx.params.get(\"items_input\")\n        p = ctx.inputs[name] if name else next(iter(ctx.inputs.values()))\n        raw = []\n        for n, line in enumerate(p.read_text(encoding=\"utf-8\").splitlines(), 1):\n            if line.strip():\n                try:\n                    raw.append(json.loads(line))\n                except ValueError as e:\n                    raise ValueError(f\"items JSONL line {n} is not JSON: {e}\") from None\n    else:\n        raise ValueError(\"batch_llm needs params.items or an input JSONL artifact\")\n    cap = min(int(ctx.params.get(\"max_items\", 500)), BATCH_LLM_HARD_MAX_ITEMS)\n    if len(raw) > cap:\n        raise ValueError(f\"{len(raw)} items > max_items {cap}: split the batch into several jobs\")\n    seen = set()\n    for it in raw:\n        if not isinstance(it, dict) or not isinstance(it.get(\"id\"), (str, int)) or not isinstance(it.get(\"prompt\"), str):\n            raise ValueError(\"every item needs an 'id' (str/int) and a 'prompt' (str)\")\n        if str(it[\"id\"]) in seen:\n            raise ValueError(f\"duplicate item id {it['id']!r}\")\n        seen.add(str(it[\"id\"]))\n    return raw\n\n\ndef _bl_on_kaggle() -> bool:\n    return Path(\"/kaggle/working\").is_dir() or bool(os.environ.get(\"KAGGLE_KERNEL_RUN_TYPE\"))\n\n\ndef _bl_model_bytes(model: str, revision) -> int | None:\n    \"\"\"Total size of the weight files, from the Hub's metadata (no download). None if it cannot be determined.\"\"\"\n    try:\n        from huggingface_hub import HfApi\n        info = HfApi().model_info(model, revision=revision, files_metadata=True)\n        exts = (\".safetensors\", \".bin\", \".pt\", \".gguf\")\n        return sum(int(s.size or 0) for s in info.siblings if s.rfilename.endswith(exts))\n    except Exception:  # noqa: BLE001\n        return None\n\n\nclass _BLEcho:\n    \"\"\"Deterministic engine for tests and dry-runs: loads nothing, answers 'echo[<task>]: <first words>'.\"\"\"\n    name, simulated = \"echo\", True\n\n    def generate(self, batch: list, temperature: float, seed: int) -> list:\n        out = []\n        for it in batch:\n            words = it[\"prompt\"].split()\n            n = max(1, min(len(words), it[\"_max_tokens\"]))\n            out.append({\"text\": f\"echo[{it.get('task') or 'general'}]: \" + \" \".join(words[:n]),\n                        \"usage\": {\"prompt_tokens\": len(words) + len((it.get(\"system\") or \"\").split()), \"completion_tokens\": n},\n                        \"finish_reason\": \"stop\" if n == len(words) else \"length\"})\n        return out\n\n\nclass _BLTransformers:\n    name, simulated = \"transformers\", False\n\n    def __init__(self, model: str, revision, chat_kwargs: dict):\n        import torch\n        from transformers import AutoModelForCausalLM, AutoTokenizer\n        self.torch = torch\n        self.tok = AutoTokenizer.from_pretrained(model, revision=revision, padding_side=\"left\")\n        if self.tok.pad_token is None:\n            self.tok.pad_token = self.tok.eos_token\n        dtype = torch.float16 if torch.cuda.is_available() else torch.float32\n        self.model = AutoModelForCausalLM.from_pretrained(model, revision=revision, torch_dtype=dtype,\n                                                          device_map=\"auto\" if torch.cuda.is_available() else None)\n        self.model.eval()\n        self.chat_kwargs = chat_kwargs or {}\n\n    def _text(self, it: dict) -> str:\n        msgs = ([{\"role\": \"system\", \"content\": it[\"system\"]}] if it.get(\"system\") else []) + [{\"role\": \"user\", \"content\": it[\"prompt\"]}]\n        if getattr(self.tok, \"chat_template\", None):\n            return self.tok.apply_chat_template(msgs, tokenize=False, add_generation_prompt=True, **self.chat_kwargs)\n        return ((it.get(\"system\") or \"\") + \"\\n\\n\" + it[\"prompt\"]).strip()\n\n    def generate(self, batch: list, temperature: float, seed: int) -> list:\n        t = self.torch\n        t.manual_seed(seed)\n        enc = self.tok([self._text(it) for it in batch], return_tensors=\"pt\", padding=True).to(self.model.device)\n        mx = max(it[\"_max_tokens\"] for it in batch)\n        kw = {\"max_new_tokens\": mx, \"pad_token_id\": self.tok.pad_token_id}\n        kw.update({\"do_sample\": True, \"temperature\": float(temperature)} if temperature > 0 else {\"do_sample\": False})\n        with t.inference_mode():\n            gen = self.model.generate(**enc, **kw)\n        out, plen = [], enc[\"input_ids\"].shape[1]\n        for i, it in enumerate(batch):\n            ids = gen[i][plen:].tolist()\n            eos = self.tok.eos_token_id\n            if eos in ids:\n                ids, reason = ids[:ids.index(eos)], \"stop\"\n            else:\n                reason = \"length\"\n            ids = ids[:it[\"_max_tokens\"]]\n            out.append({\"text\": self.tok.decode(ids, skip_special_tokens=True).strip(),\n                        \"usage\": {\"prompt_tokens\": int(enc[\"attention_mask\"][i].sum()), \"completion_tokens\": len(ids)},\n                        \"finish_reason\": reason})\n        return out\n\n\nclass _BLVllm:\n    name, simulated = \"vllm\", False\n\n    def __init__(self, model: str, revision, chat_kwargs: dict):\n        from vllm import LLM  # only if the image already has it: this task never pip-installs an engine\n        self.llm = LLM(model=model, revision=revision, dtype=\"half\", enforce_eager=True)\n        self.chat_kwargs = chat_kwargs or {}\n\n    def generate(self, batch: list, temperature: float, seed: int) -> list:\n        from vllm import SamplingParams\n        convs = [([{\"role\": \"system\", \"content\": it[\"system\"]}] if it.get(\"system\") else []) + [{\"role\": \"user\", \"content\": it[\"prompt\"]}]\n                 for it in batch]\n        outs = []\n        for it, conv in zip(batch, convs):\n            sp = SamplingParams(max_tokens=it[\"_max_tokens\"], temperature=float(temperature), seed=seed)\n            r = self.llm.chat([conv], sp, use_tqdm=False, chat_template_kwargs=self.chat_kwargs)[0]\n            o = r.outputs[0]\n            outs.append({\"text\": o.text.strip(), \"usage\": {\"prompt_tokens\": len(r.prompt_token_ids), \"completion_tokens\": len(o.token_ids)},\n                         \"finish_reason\": o.finish_reason})\n        return outs\n\n\ndef _bl_engine(ctx):\n    engine = ctx.params.get(\"engine\", \"transformers\")\n    if engine == \"echo\":\n        return _BLEcho()\n    if engine not in (\"transformers\", \"vllm\"):\n        raise ValueError(f\"unknown engine {engine!r} (transformers | vllm | echo)\")\n    model = ctx.params.get(\"model\")\n    import re as _re\n    if not model or not _re.fullmatch(r\"[A-Za-z0-9][\\w.-]*/[\\w.-]+\", str(model)):\n        raise ValueError(\"params.model must be a Hugging Face repo id 'owner/name'\")\n    if not _bl_on_kaggle() and os.environ.get(\"NEXUS_BATCH_LLM_ALLOW_HERE\") != \"1\":\n        raise RuntimeError(\"refusing to download model weights outside a Kaggle kernel (owner machines are never used \"\n                           \"implicitly; set NEXUS_BATCH_LLM_ALLOW_HERE=1 on a machine you chose for this)\")\n    cap_gb = float(ctx.params.get(\"max_model_gb\", 8.0))\n    size = _bl_model_bytes(model, ctx.params.get(\"model_revision\"))\n    ctx.metrics[\"model_weight_bytes\"] = size\n    if size is None:\n        raise RuntimeError(f\"cannot determine the weight size of {model} before download; refusing (max_model_gb={cap_gb})\")\n    if size > cap_gb * 2 ** 30:\n        raise RuntimeError(f\"{model} weights are {size / 2 ** 30:.2f} GiB > max_model_gb {cap_gb}\")\n    t0 = time.time()\n    eng = (_BLVllm if engine == \"vllm\" else _BLTransformers)(model, ctx.params.get(\"model_revision\"), ctx.params.get(\"chat_template_kwargs\") or {})\n    ctx.metrics[\"model_load_s\"] = round(time.time() - t0, 2)\n    ctx.metrics[\"model_download_bytes\"] = size\n    return eng\n\n\ndef _bl_generate(eng, batch: list, temperature: float, seed: int) -> list:\n    \"\"\"One batch; on an engine error (e.g. CUDA OOM) retry the items one by one, then record per-item errors.\"\"\"\n    t0 = time.time()\n    try:\n        res = eng.generate(batch, temperature, seed)\n        dt = (time.time() - t0) / max(1, len(batch))\n        return [{**r, \"latency_s\": round(dt, 4), \"error\": None} for r in res]\n    except Exception as e:  # noqa: BLE001\n        if len(batch) == 1:\n            return [{\"text\": None, \"usage\": None, \"finish_reason\": \"error\", \"latency_s\": round(time.time() - t0, 4),\n                     \"error\": f\"{type(e).__name__}: {str(e)[:300]}\"}]\n        try:\n            eng.torch.cuda.empty_cache()  # type: ignore[attr-defined]\n        except Exception:  # noqa: BLE001\n            pass\n        return [r for it in batch for r in _bl_generate(eng, [it], temperature, seed)]\n\n\n@task(\"batch_llm\")\ndef task_batch_llm(ctx) -> dict:\n    items = _bl_items(ctx)\n    p = ctx.params\n    tok_cap = min(int(p.get(\"max_new_tokens\", 256)), BATCH_LLM_HARD_MAX_TOKENS)\n    max_chars = int(p.get(\"max_prompt_chars\", 16000))\n    bs, part_size = max(1, int(p.get(\"batch_size\", 8))), max(1, int(p.get(\"part_size\", 32)))\n    temperature, seed = float(p.get(\"temperature\", 0.0)), int(p.get(\"seed\", 0))\n    fmt = p.get(\"output_format\", \"jsonl\")\n    if fmt not in (\"jsonl\", \"json\"):\n        raise ValueError(\"output_format must be jsonl or json\")\n    budget = float(p.get(\"time_budget_s\") or 0.85 * float(ctx.bundle.get(\"max_runtime_s\") or 3600))\n    parts = [items[i:i + part_size] for i in range(0, len(items), part_size)]\n    state = {\"parts_total\": len(parts), \"done\": [], \"part_files\": {}, **ctx.resume_state}\n    done = set(int(i) for i in state[\"done\"])\n    skipped = sorted(done)\n    started = time.time()\n    eng = None\n    ran, n_ok, n_err, ptoks, ctoks, gen_s = [], 0, 0, 0, 0, 0.0\n    stop_after = p.get(\"simulate_loss_after_parts\")\n    for pi, part in enumerate(parts):\n        if pi in done:\n            ctx.log(f\"part {pi}: already done in an earlier attempt (checkpoint) - skipped\")\n            continue\n        if ran and time.time() - started > budget:\n            ctx.metrics.update(parts_run_this_attempt=ran, parts_skipped=skipped, items_ok=n_ok, items_error=n_err)\n            raise BatchLLMBudgetReached(f\"time budget {budget:.0f}s reached after {len(ran)} part(s); resume from checkpoint\")\n        if eng is None:\n            eng = _bl_engine(ctx)\n        rows, todo = [], []\n        for it in part:\n            row = {\"id\": it[\"id\"], \"task\": it.get(\"task\")}\n            if len(it[\"prompt\"]) + len(it.get(\"system\") or \"\") > max_chars:\n                rows.append({**row, \"text\": None, \"usage\": None, \"finish_reason\": \"error\", \"latency_s\": 0.0,\n                             \"error\": f\"prompt longer than max_prompt_chars {max_chars}\"})\n                continue\n            todo.append({**it, \"_max_tokens\": max(1, min(int(it.get(\"max_tokens\") or tok_cap), tok_cap))})\n            rows.append(row)\n        t0 = time.time()\n        results = {}\n        for b in range(0, len(todo), bs):\n            batch = todo[b:b + bs]\n            for it, r in zip(batch, _bl_generate(eng, batch, temperature, seed)):\n                results[str(it[\"id\"])] = r\n        gen_s += time.time() - t0\n        for row in rows:\n            if \"error\" not in row:\n                row.update(results[str(row[\"id\"])])\n            if row[\"error\"]:\n                n_err += 1\n            else:\n                n_ok += 1\n                ptoks += row[\"usage\"][\"prompt_tokens\"]\n                ctoks += row[\"usage\"][\"completion_tokens\"]\n        name = f\"batch_llm_part_{pi:04d}.a{ctx.attempt}.jsonl\"\n        f = ctx.work / name\n        f.write_text(\"\".join(json.dumps(r, ensure_ascii=False) + \"\\n\" for r in rows), encoding=\"utf-8\")\n        a = ctx.artifact(f, \"analysis\", part=pi, model=p.get(\"model\"), engine=eng.name, simulated=eng.simulated)\n        ran.append(pi)\n        state[\"done\"] = sorted(done | set(ran))\n        state[\"part_files\"][str(pi)] = {\"name\": a[\"name\"], \"sha256\": a[\"sha256\"], \"items\": len(rows), \"attempt\": ctx.attempt}\n        ctx.checkpoint(f\"part_{pi}\", json.loads(json.dumps(state)))\n        if stop_after is not None and ctx.attempt == 1 and len(ran) >= int(stop_after) and len(state[\"done\"]) < len(parts):\n            ctx.metrics.update(parts_run_this_attempt=ran, parts_skipped=skipped, items_ok=n_ok, items_error=n_err)\n            raise SimulatedWorkerLoss(f\"simulated worker loss after {len(ran)} part(s) (params.simulate_loss_after_parts)\")\n    summary = {\"model\": p.get(\"model\"), \"model_revision\": p.get(\"model_revision\"), \"model_licence\": p.get(\"model_licence\", \"unverified\"),\n               \"engine\": eng.name if eng else p.get(\"engine\", \"transformers\"), \"simulated\": bool(eng.simulated) if eng else p.get(\"engine\") == \"echo\",\n               \"items_total\": len(items), \"parts_total\": len(parts), \"part_files\": state[\"part_files\"], \"output_format\": fmt,\n               \"this_attempt\": {\"attempt\": ctx.attempt, \"parts_run\": ran, \"parts_skipped\": skipped, \"items_ok\": n_ok,\n                                \"items_error\": n_err, \"prompt_tokens\": ptoks, \"completion_tokens\": ctoks,\n                                \"generate_s\": round(gen_s, 3),\n                                \"completion_tokens_per_s\": round(ctoks / gen_s, 2) if gen_s > 0 else None},\n               \"limits\": {\"max_new_tokens\": tok_cap, \"max_prompt_chars\": max_chars, \"batch_size\": bs, \"part_size\": part_size,\n                          \"time_budget_s\": round(budget, 1), \"max_model_gb\": float(p.get(\"max_model_gb\", 8.0))},\n               \"temperature\": temperature, \"seed\": seed, \"persistent_endpoint\": False}\n    ctx.write_json_artifact(\"batch_llm_summary.json\", summary)\n    return {\"batch_llm\": {k: summary[k] for k in (\"model\", \"engine\", \"simulated\", \"items_total\", \"parts_total\")},\n            \"parts_run_this_attempt\": ran, \"parts_skipped\": skipped, \"items_ok\": n_ok, \"items_error\": n_err,\n            \"completion_tokens\": ctoks, \"completion_tokens_per_s\": summary[\"this_attempt\"][\"completion_tokens_per_s\"],\n            \"model_load_s\": ctx.metrics.get(\"model_load_s\")}\n\n\n# NEXUS_EXTRA_TASKS\nif __name__ == \"__main__\":\n    sys.exit(main())\n";
export const STUDIO_SCRIPT = "\"\"\"NEXUS Studio session on Kaggle: runs the FULL NEXUS app (the same UI and features as on Windows) for the owner.\n\nPushed as a private Kaggle script kernel by the Cloudflare control plane (cloudflare/src/studio.js) with its config\nembedded below. Steps:\n  1. restore the previous session's NEXUS_HOME (projects, database, settings) from the mounted output of the last\n     studio kernel, if the control plane attached one;\n  2. install the system/Python dependencies the app needs (Kaggle images already ship torch, ffmpeg, numpy...);\n  3. clone the NEXUS repository at the configured ref and start `python -m nexus serve` on 127.0.0.1 with\n     NEXUS_API_TOKEN set (hosted mode: every request needs that bearer token; only the Cloudflare gateway has it);\n  4. open a Cloudflare quick tunnel to it and report the URL to the control plane, which proxies the owner's browser\n     to it after its own login check;\n  5. heartbeat every 30 s; stop when the owner presses Stop, when the UI has been idle too long, or before Kaggle's\n     session limit; then shut the app down cleanly and save NEXUS_HOME (without models and caches) to\n     /kaggle/working so the next session continues where this one stopped.\nStandard library only. Never prints the token or the callback secret.\n\"\"\"\nfrom __future__ import annotations\n\nimport base64\nimport json\nimport os\nimport re\nimport shutil\nimport signal\nimport subprocess\nimport sys\nimport threading\nimport time\nimport urllib.request\nfrom pathlib import Path\n\n_CONFIG_B64 = \"\"  # replaced by the control plane: repo, ref, token, callback, secret, max_s\n\nCFG = json.loads(base64.b64decode(_CONFIG_B64)) if _CONFIG_B64 else {}\nT0 = time.time()\nWORK = Path(\"/kaggle/working\") if Path(\"/kaggle/working\").is_dir() else Path(\"studio_out\")\nHOME = Path(\"/tmp/nexus_home\")\nSRC = Path(\"/tmp/nexus_src\")\nSAVE = WORK / \"nexus_home\"\nSKIP_SAVE = {\"models\", \"cache\", \"tmp\", \"logs\", \"run\"}  # re-creatable; models are re-downloaded on first use\nLOG: list[str] = []\nSTATE = {\"restored\": False, \"saved\": False, \"safe_to_save\": False}\nSECRETS: dict = {}  # session-only secrets (never written to disk or the output)\n\n\ndef log(msg: str) -> None:\n    line = f\"{time.strftime('%H:%M:%S')} {msg}\"\n    for secret in (CFG.get(\"token\"), CFG.get(\"secret\"), *SECRETS.values()):\n        if secret:\n            line = line.replace(secret, \"***\")\n    LOG.append(line)\n    print(line, flush=True)\n\n\ndef report(state: str, **extra) -> dict:\n    \"\"\"POST to the control plane. Returns its reply ({\"stop\": bool}); never raises.\"\"\"\n    body = json.dumps({\"secret\": CFG[\"secret\"], \"session\": CFG[\"session\"], \"state\": state, \"log\": LOG[-25:], **extra}).encode()\n    req = urllib.request.Request(CFG[\"callback\"], data=body, method=\"POST\",\n                                 headers={\"Content-Type\": \"application/json\", \"User-Agent\": \"nexus-studio/1\"})\n    try:\n        with urllib.request.urlopen(req, timeout=20) as r:  # noqa: S310 - https control plane URL from the config\n            return json.loads(r.read() or b\"{}\")\n    except Exception as e:  # noqa: BLE001\n        print(f\"report {state} failed: {type(e).__name__}\", flush=True)\n        return {}\n\n\ndef sh(cmd: list[str], timeout: float = 1800, check: bool = False) -> int:\n    log(\"$ \" + \" \".join(cmd)[:160])\n    try:\n        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)\n    except subprocess.TimeoutExpired:\n        log(f\"  timed out after {timeout:.0f}s\")\n        return 124\n    if r.returncode != 0:\n        log(f\"  exit {r.returncode}: {(r.stderr or r.stdout)[-600:]}\")\n        if check:\n            raise RuntimeError(f\"{cmd[0]} failed\")\n    return r.returncode\n\n\n# ---------------------------------------------------------------- 1. restore\ndef find_saved() -> Path | None:\n    \"\"\"The previous session's saved NEXUS_HOME. Kaggle mounts a notebook's output at\n    /kaggle/input/notebooks/<owner>/<slug>/ (seen live 2026-11-14); older layouts used /kaggle/input/<slug>/.\"\"\"\n    root = Path(\"/kaggle/input\")\n    if not root.is_dir():\n        return None\n    want = (CFG.get(\"restore_from\") or \"\").split(\"/\")[-1]\n    hits = [p for p in root.rglob(\"nexus_home\") if p.is_dir() and len(p.relative_to(root).parts) <= 5]\n    hits.sort(key=lambda p: (want not in p.parts, len(p.parts)))\n    return hits[0] if hits else None\n\n\ndef restore() -> None:\n    HOME.mkdir(parents=True, exist_ok=True)\n    src = find_saved()\n    if src is None:\n        if CFG.get(\"restore_from\"):\n            # never start empty when work was expected: saving later would hide the real saved work\n            raise RuntimeError(f\"previous studio output {CFG['restore_from']} was attached but not found under /kaggle/input\")\n        log(\"no previous studio state attached: starting with an empty NEXUS_HOME\")\n        return\n    shutil.copytree(src, HOME, dirs_exist_ok=True)\n    n = sum(1 for _ in HOME.rglob(\"*\"))\n    log(f\"restored previous session from {src.parent.name} ({n} files)\")\n    STATE[\"restored\"] = True\n\n\n# ---------------------------------------------------------------- 2+3. install and start\nAPT = [\"espeak-ng\", \"fonts-noto-core\", \"fonts-noto-cjk\", \"fonts-dejavu-core\", \"tesseract-ocr\", \"tesseract-ocr-ara\",\n       \"libcairo2-dev\", \"libpango1.0-dev\", \"pkg-config\"]\nOPTIONAL_PIP = {\"manim\", \"llama-cpp-python\", \"pytest\"}  # slow to build / not needed to serve; installed in the background\n\n\ndef install() -> None:\n    if not shutil.which(\"ffmpeg\"):\n        APT.insert(0, \"ffmpeg\")\n    sh([\"apt-get\", \"update\", \"-qq\"], 600)\n    sh([\"apt-get\", \"install\", \"-y\", \"-qq\", \"--no-install-recommends\", *APT], 1200)\n    sh([\"git\", \"clone\", \"--depth\", \"1\", \"-b\", CFG.get(\"ref\", \"main\"), CFG[\"repo\"], str(SRC)], 600, check=True)\n    reqs = []\n    for line in (SRC / \"requirements.txt\").read_text(encoding=\"utf-8\").splitlines():\n        name = line.split(\"#\")[0].strip()\n        if name and re.split(r\"[<>=\\[ ]\", name)[0].lower() not in OPTIONAL_PIP:\n            reqs.append(name)\n    sh([sys.executable, \"-m\", \"pip\", \"install\", \"-q\", *reqs], 2400, check=True)\n\n    install_llama({**os.environ, \"LD_LIBRARY_PATH\": cuda_lib_path()})\n\n    def background() -> None:\n        sh([sys.executable, \"-m\", \"pip\", \"install\", \"-q\", \"manim\"], 2400)\n        log(\"optional package manim done\")\n\n    threading.Thread(target=background, daemon=True).start()\n\n\ndef fetch_secrets() -> dict:\n    \"\"\"Session secrets (YouTube channel keys) from the control plane; kept in memory, passed to the app as env vars.\"\"\"\n    url = CFG[\"callback\"].rsplit(\"/\", 1)[0] + \"/secrets\"\n    body = json.dumps({\"secret\": CFG[\"secret\"], \"session\": CFG[\"session\"]}).encode()\n    req = urllib.request.Request(url, data=body, method=\"POST\", headers={\"Content-Type\": \"application/json\", \"User-Agent\": \"nexus-studio/1\"})\n    try:\n        with urllib.request.urlopen(req, timeout=20) as r:  # noqa: S310\n            got = json.loads(r.read() or b\"{}\").get(\"env\") or {}\n    except Exception as e:  # noqa: BLE001\n        log(f\"could not fetch session secrets ({type(e).__name__}); YouTube stays unconnected this session\")\n        return {}\n    ok = {k: str(v) for k, v in got.items() if re.fullmatch(r\"NEXUS_PUB_[A-Z0-9_]{1,60}\", k)}\n    if ok:\n        log(\"YouTube channel keys received for this session\")\n    return ok\n\n\ndef register_youtube() -> None:\n    code = (\"from nexus.intelligence.publishing import engine, youtube_oauth as y; \"\n            \"engine.connect_account('youtube', 'main', secret_ref=y.names('main')['refresh_token'], scopes=y.SCOPES, \"\n            \"note='connected from the Cloudflare panel')\")\n    rc = sh([sys.executable, \"-c\", code], 120)\n    log(\"YouTube channel registered in NEXUS (account 'main')\" if rc == 0 else \"YouTube account registration failed (see log)\")\n\n\n\ndef cuda_lib_path() -> str:\n    \"\"\"Kaggle ships CUDA 13 system-wide, but the CUDA 12 runtime/cuBLAS that the llama.cpp cu12 wheel needs are in pip\n    packages (site-packages/nvidia/<lib>/lib, seen live 2026-11-14) that are not on LD_LIBRARY_PATH.\"\"\"\n    import glob\n    dirs = sorted({str(Path(p).parent) for pat in (\"nvidia/*/lib/libcudart.so.12\", \"nvidia/*/lib/libcublas*.so.12\")\n                   for base in sys.path if base.endswith((\"site-packages\", \"dist-packages\")) for p in glob.glob(os.path.join(base, pat))})\n    return \":\".join(dirs + [x for x in os.environ.get(\"LD_LIBRARY_PATH\", \"\").split(\":\") if x])\n\n\ndef llama_ok(env: dict) -> bool:\n    code = \"import llama_cpp, sys; llama_cpp.llama_backend_init(); print('llama ok', llama_cpp.__version__)\"\n    r = subprocess.run([sys.executable, \"-c\", code], capture_output=True, text=True, env=env, timeout=120)\n    if r.returncode != 0:\n        log(f\"llama.cpp check failed: {(r.stderr or r.stdout)[-300:]}\")\n    return r.returncode == 0\n\n\ndef install_llama(env: dict) -> None:\n    \"\"\"The local LLM (scripts, titles, translation checks). Order: CUDA 12 wheel -> CPU wheel -> build from source.\"\"\"\n    cuda = \"https://abetlen.github.io/llama-cpp-python/whl/cu124\"\n    cpu = \"https://abetlen.github.io/llama-cpp-python/whl/cpu\"\n    sh([sys.executable, \"-m\", \"pip\", \"install\", \"-q\", \"diskcache>=5.6.1\", \"jinja2>=2.11.3\", \"typing-extensions>=4.5.0\"], 600)\n    for extra in (cuda, cpu):\n        sh([sys.executable, \"-m\", \"pip\", \"install\", \"-q\", \"--force-reinstall\", \"--no-deps\", \"--only-binary=:all:\", \"llama-cpp-python\",\n            \"--extra-index-url\", extra], 1800)\n        if llama_ok(env):\n            log(f\"llama.cpp ready ({'GPU' if extra == cuda else 'CPU'})\")\n            return\n    sh([sys.executable, \"-m\", \"pip\", \"install\", \"-q\", \"--force-reinstall\", \"--no-binary=llama-cpp-python\", \"llama-cpp-python\"], 3600)\n    log(\"llama.cpp ready (built from source)\" if llama_ok(env) else \"llama.cpp NOT available: scripts use the fallback writer\")\n\n\ndef start_app() -> subprocess.Popen:\n    env = {**os.environ, **SECRETS, \"LD_LIBRARY_PATH\": cuda_lib_path(), \"NEXUS_HOME\": str(HOME), \"NEXUS_API_TOKEN\": CFG[\"token\"], \"NEXUS_PORT\": \"8765\",\n           \"PYTHONUNBUFFERED\": \"1\", \"NEXUS_EMBEDDED_WORKER\": \"1\"}\n    out = open(WORK / \"nexus_app.log\", \"a\", encoding=\"utf-8\")  # noqa: SIM115 - kept open for the child\n    p = subprocess.Popen([sys.executable, \"-m\", \"nexus\", \"serve\", \"--host\", \"127.0.0.1\", \"--port\", \"8765\"],\n                         cwd=SRC, env=env, stdout=out, stderr=subprocess.STDOUT)\n    for _ in range(240):\n        if p.poll() is not None:\n            raise RuntimeError(f\"the NEXUS app exited with code {p.returncode}: see nexus_app.log\")\n        try:\n            with urllib.request.urlopen(\"http://127.0.0.1:8765/api/v1/health/live\", timeout=3):  # noqa: S310\n                log(\"NEXUS app is up on 127.0.0.1:8765\")\n                return p\n        except Exception:  # noqa: BLE001 - not up yet (or 401: still means it is serving)\n            try:\n                req = urllib.request.Request(\"http://127.0.0.1:8765/api/health\", headers={\"Authorization\": f\"Bearer {CFG['token']}\"})\n                with urllib.request.urlopen(req, timeout=3):  # noqa: S310\n                    log(\"NEXUS app is up on 127.0.0.1:8765\")\n                    return p\n            except Exception:  # noqa: BLE001\n                pass\n        time.sleep(2)\n    raise RuntimeError(\"the NEXUS app did not become healthy within 8 minutes\")\n\n\n# ---------------------------------------------------------------- 4. tunnel\ndef tunnel() -> tuple[subprocess.Popen, str]:\n    exe = Path(\"/tmp/cloudflared\")\n    if not exe.exists():\n        url = \"https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64\"\n        with urllib.request.urlopen(url, timeout=120) as r, open(exe, \"wb\") as f:  # noqa: S310\n            shutil.copyfileobj(r, f)\n        exe.chmod(0o755)\n    p = subprocess.Popen([str(exe), \"tunnel\", \"--no-autoupdate\", \"--url\", \"http://127.0.0.1:8765\"],\n                         stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)\n    found: list[str] = []\n\n    def reader() -> None:\n        for line in p.stdout:  # type: ignore[union-attr]\n            m = re.search(r\"https://[a-z0-9-]+\\.trycloudflare\\.com\", line)\n            if m and not found:\n                found.append(m.group(0))\n\n    threading.Thread(target=reader, daemon=True).start()\n    for _ in range(90):\n        if found:\n            log(f\"tunnel ready ({found[0].split('//')[1].split('.')[0][:6]}\u2026)\")\n            return p, found[0]\n        if p.poll() is not None:\n            break\n        time.sleep(1)\n    raise RuntimeError(\"cloudflared did not open a tunnel\")\n\n\n# ---------------------------------------------------------------- 5. save\ndef save(app: subprocess.Popen | None) -> None:\n    if not STATE[\"safe_to_save\"]:\n        log(\"nothing saved: the session failed before your previous work was loaded (it is still kept on Kaggle)\")\n        return\n    if app and app.poll() is None:\n        app.send_signal(signal.SIGTERM)\n        try:\n            app.wait(45)\n        except subprocess.TimeoutExpired:\n            app.kill()\n    if not HOME.exists():\n        return\n    shutil.rmtree(SAVE, ignore_errors=True)\n    shutil.copytree(HOME, SAVE, ignore=lambda d, names: [n for n in names if Path(d) == HOME and n in SKIP_SAVE])\n    size = sum(f.stat().st_size for f in SAVE.rglob(\"*\") if f.is_file())\n    STATE[\"saved\"] = True\n    log(f\"saved NEXUS_HOME for the next session ({size / 2**20:.0f} MB, models and caches excluded)\")\n\n\ndef main() -> int:\n    WORK.mkdir(parents=True, exist_ok=True)\n    max_s = float(CFG.get(\"max_s\", 6 * 3600))\n    app = cf = None\n    try:\n        report(\"installing\")\n        restore()\n        STATE[\"safe_to_save\"] = True\n        install()\n        report(\"starting\")\n        SECRETS.update(fetch_secrets())\n        app = start_app()\n        if \"NEXUS_PUB_YOUTUBE_MAIN_REFRESH_TOKEN\" in SECRETS:\n            os.environ.update({\"NEXUS_HOME\": str(HOME)})\n            os.chdir(SRC)\n            register_youtube()\n        cf, url = tunnel()\n        reply = report(\"ready\", url=url)\n        while not reply.get(\"stop\"):\n            if time.time() - T0 > max_s - 20 * 60:\n                log(\"Kaggle session limit is near: stopping to save your work\")\n                break\n            if app.poll() is not None:\n                log(f\"the NEXUS app exited (code {app.returncode}); see nexus_app.log in the output\")\n                break\n            if cf.poll() is not None:\n                log(\"tunnel dropped: reopening\")\n                cf, url = tunnel()\n                report(\"ready\", url=url)\n            time.sleep(30)\n            reply = report(\"ready\", url=url)\n        report(\"saving\")\n        save(app)\n        report(\"stopped\", saved=STATE[\"saved\"])\n        return 0\n    except Exception as e:  # noqa: BLE001 - always try to keep the owner's work\n        log(f\"ERROR: {type(e).__name__}: {e}\")\n        try:\n            save(app)\n        except Exception as e2:  # noqa: BLE001\n            log(f\"save failed: {e2}\")\n        report(\"error\", error=f\"{type(e).__name__}: {e}\", saved=STATE[\"saved\"])\n        return 0  # exit 0 so Kaggle keeps the saved output for the next session\n    finally:\n        if cf and cf.poll() is None:\n            cf.terminate()\n        (WORK / \"studio_log.txt\").write_text(\"\\n\".join(LOG), encoding=\"utf-8\")\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n";
